int cmp(const void *a, const void *b) {
    return *(int*)a - *(int*)b;
}

int can(int *gaps, int n, int mid) {
    int pos[100];
    pos[0] = 0;
    for (int i = 1; i < n; i++) {
        pos[i] = pos[i-1] + mid;
        if (pos[i] > 1440 - mid) return 0;
    }
    for (int i = 0; i < n; i++) {
        int j = (i + 1) % n;
        int diff = (pos[j] - pos[i] + 1440) % 1440;
        if (diff < mid && i != n-1) return 0;
    }
    return 1;
}

