// Check if we can place all N+1 participants with min gap >= g
// Takahashi at 0, participant i at d[i] or 24-d[i]
// Use bitmask DP (N <= 20)
int check(double g) {
    // bitmask DP: state = set of participants placed
    // Try all 2^N assignments
    int total = 1 << N;
    for (int mask = 0; mask < total; mask++) {
        double pos[25];
        pos[0] = 0;
        int cnt = 1;
        int ok = 1;
        for (int i = 0; i < N; i++) {
            double p = (mask >> i & 1) ? 24 - d[i] : d[i];
            for (int j = 0; j < cnt; j++)
                if (dist(p, pos[j]) < g - 1e-9) { ok = 0; break; }
            if (!ok) break;
            pos[cnt++] = p;
        }
        if (ok) return 1;
    }
    return 0;
}

