int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    long long T;
    cin >> N >> T;
    vector<long long> d(N);
    for (int i = 0; i < N; i++) {
        cin >> d[i];
    }

    // Binary search over possible minimum gap
    long long lo = 0, hi = T;
    while (lo < hi) {
        long long mid = (lo + hi + 1) / 2;

        // Check if we can place all with at least mid distance
        vector<long long> pos;
        pos.push_back(0); // Takahashi at 0
        for (int i = 0; i < N; i++) {
            long long p = d[i] % T;
            if (p < 0) p += T;
            pos.push_back(p);
        }
        sort(pos.begin(), pos.end());
        // Remove duplicates
        pos.erase(unique(pos.begin(), pos.end()), pos.end());

        int m = pos.size();
        bool ok = false;
        // Try all possible starting rotations
        for (int start = 0; start < m; start++) {
            long long last = pos[start];
            int cnt = 1;
            for (int i = 1; i < m; i++) {
                long long cur = pos[(start + i) % m];
                long long gap = (cur - last + T) % T;
                if (gap >= mid) {
                    cnt++;
                    last = cur;
                }
            }
            // Also need to check wrap-around gap from last to first in chosen set
            long long wrap = (pos[start] - last + T) % T;
            if (wrap >= mid) {
                cnt++;
            }
            if (cnt >= m) {
                ok = true;
                break;
            }
        }

        if (ok) {
            lo = mid;
        } else {
            hi = mid - 1;
        }
    }

    cout << lo << "\n";
    return 0;
}

