#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;
    vector<long long> D(N);
    for (int i = 0; i < N; i++) cin >> D[i];

    const int MAXT = 24;
    vector<int> cnt(MAXT + 1, 0);
    for (long long x : D) {
        if (0 <= x && x <= MAXT) cnt[(int)x]++;
    }

    // If any participant has distance 0 or 24 from Takahashi, or
    // some distance in 1..23 appears 3 or more times, impossible to place
    // all uniquely on the clock.
    if (cnt[0] > 0 || cnt[24] > 0) {
        cout << 0 << '\n';
        return 0;
    }
    for (int d = 1; d <= 23; d++) {
        if (cnt[d] >= 3) {
            cout << 0 << '\n';
            return 0;
        }
    }

    // Takahashi is at 0.
    // For each distance d:
    // - if cnt[d] == 1, choose either d or 24-d
    // - if cnt[d] == 2, both d and 24-d must be occupied
    vector<int> single;
    vector<int> fixedPos = {0};

    for (int d = 1; d <= 23; d++) {
        if (cnt[d] == 1) single.push_back(d);
        else if (cnt[d] == 2) {
            fixedPos.push_back(d);
            fixedPos.push_back(24 - d);
        }
    }

    int m = (int)single.size();
    int ans = 0;

    for (int mask = 0; mask < (1 << m); mask++) {
        vector<int> pos = fixedPos;
        for (int i = 0; i < m; i++) {
            int d = single[i];
            if (mask & (1 << i)) pos.push_back(d);
            else pos.push_back(24 - d);
        }

        int mn = 24;
        for (int i = 0; i < (int)pos.size(); i++) {
            for (int j = i + 1; j < (int)pos.size(); j++) {
                int diff = abs(pos[i] - pos[j]);
                diff = min(diff, 24 - diff);
                mn = min(mn, diff);
            }
        }
        ans = max(ans, mn);
    }

    cout << ans << '\n';
    return 0;
}

