import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int N = fs.nextInt();
        int[] D = new int[N];
        for (int i = 0; i < N; i++) D[i] = fs.nextInt();

        // There are 24 possible clock positions: 0..23.
        // Takahashi is fixed at 0.
        // For each participant with value d, their time can be either d or 24-d.
        // We want to maximize the minimum circular distance among all chosen positions.
        //
        // N is small enough for brute force over 2^N choices.

        int ans = 0;
        int totalMasks = 1 << N;

        for (int mask = 0; mask < totalMasks; mask++) {
            int[] pos = new int[N + 1];
            pos[0] = 0; // Takahashi
            for (int i = 0; i < N; i++) {
                if (((mask >> i) & 1) == 0) pos[i + 1] = D[i];
                else pos[i + 1] = 24 - D[i];
            }

            int minGap = 24;
            boolean bad = false;

            for (int i = 0; i <= N; i++) {
                for (int j = i + 1; j <= N; j++) {
                    int diff = Math.abs(pos[i] - pos[j]);
                    int dist = Math.min(diff, 24 - diff);
                    if (dist == 0) {
                        bad = true;
                        minGap = 0;
                        break;
                    }
                    minGap = Math.min(minGap, dist);
                }
                if (bad) break;
            }

            ans = Math.max(ans, minGap);
        }

        System.out.println(ans);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
